package ru.local.glasshome;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.service.notification.*;import android.view.*;import android.widget.*;import java.util.*;
public final class Island {
 public static class Item {public String key,pkg,app,title,text;public long when;public PendingIntent open;public Drawable icon;}
 private static final LinkedHashMap<String,Item> items=new LinkedHashMap<>();private static final HashMap<String,String> recent=new HashMap<>();private static MediaAccess service;private static View bubble;private static Handler handler=new Handler(Looper.getMainLooper());private static String shownKey;private static BroadcastReceiver screenOff;
 public static synchronized java.util.List<Item> list(){ArrayList<Item> list=new ArrayList<>(items.values());list.sort((a,b)->Long.compare(b.when,a.when));return list;}
 public static void connected(MediaAccess s){service=s;try{StatusBarNotification[] ns=s.getActiveNotifications();if(ns!=null)for(StatusBarNotification n:ns)posted(s,n,false);}catch(Exception ignored){}if(screenOff==null){screenOff=new BroadcastReceiver(){public void onReceive(Context c,Intent i){hide();}};s.registerReceiver(screenOff,new IntentFilter(Intent.ACTION_SCREEN_OFF));}}
 public static void disconnected(){hide();if(service!=null&&screenOff!=null)try{service.unregisterReceiver(screenOff);}catch(Exception ignored){}screenOff=null;service=null;items.clear();recent.clear();}
 public static void posted(MediaAccess s,StatusBarNotification sbn,boolean announce){if(sbn==null||sbn.getPackageName().equals(s.getPackageName()))return;Notification n=sbn.getNotification();if((n.flags&Notification.FLAG_GROUP_SUMMARY)!=0)return;Item item=new Item();item.key=sbn.getKey();item.pkg=sbn.getPackageName();item.when=sbn.getPostTime();item.open=n.contentIntent;try{item.app=s.getPackageManager().getApplicationLabel(s.getPackageManager().getApplicationInfo(item.pkg,0)).toString();}catch(Exception e){item.app=item.pkg;}CharSequence title=n.extras.getCharSequence(Notification.EXTRA_TITLE),body=n.extras.getCharSequence(Notification.EXTRA_BIG_TEXT);if(body==null)body=n.extras.getCharSequence(Notification.EXTRA_TEXT);item.title=title==null?item.app:title.toString();item.text=body==null?"":body.toString();if(n.visibility==Notification.VISIBILITY_SECRET){item.title=item.app;item.text="Новое уведомление";}try{item.icon=n.getSmallIcon()==null?null:n.getSmallIcon().loadDrawable(s);}catch(Exception ignored){}
 synchronized(Island.class){items.put(item.key,item);while(items.size()>100)items.remove(items.keySet().iterator().next());}String signature=item.title+"\n"+item.text;String previous=recent.put(item.key,signature);if(recent.size()>150)recent.clear();if(!announce||signature.equals(previous)||sbn.isOngoing())return;NotificationListenerService.Ranking ranking=new NotificationListenerService.Ranking();try{if(s.getCurrentRanking().getRanking(item.key,ranking)&&ranking.getImportance()<3)return;}catch(Exception ignored){}handler.post(()->show(s,item));}
 public static void removed(String key){synchronized(Island.class){items.remove(key);recent.remove(key);}if(key.equals(shownKey))hide();}
 public static void dismiss(String key){MediaAccess s=service;if(s!=null)s.cancelNotification(key);}
 public static void open(Context c,Item item){hide();if(item.open!=null)try{item.open.send();return;}catch(Exception ignored){}Intent i=c.getPackageManager().getLaunchIntentForPackage(item.pkg);if(i!=null){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(i);}}
 public static void hide(){handler.removeCallbacks(close);View old=bubble;bubble=null;shownKey=null;if(old!=null&&service!=null)try{((WindowManager)service.getSystemService(Context.WINDOW_SERVICE)).removeView(old);}catch(Exception ignored){}}
 static final Runnable close=()->hide();static int dp(Context c,float v){return (int)(v*c.getResources().getDisplayMetrics().density+.5f);}
 static void show(MediaAccess s,Item item){KeyguardManager keyguard=(KeyguardManager)s.getSystemService(Context.KEYGUARD_SERVICE);if(keyguard.isKeyguardLocked())return;if(!android.provider.Settings.canDrawOverlays(s))return;hide();service=s;WindowManager wm=(WindowManager)s.getSystemService(Context.WINDOW_SERVICE);LinearLayout root=new LinearLayout(s);root.setGravity(Gravity.CENTER_VERTICAL);root.setPadding(dp(s,14),dp(s,10),dp(s,10),dp(s,10));GradientDrawable glass=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xf22a354b,0xf30d1726});glass.setCornerRadius(dp(s,30));glass.setStroke(dp(s,1),0x70c3e7fa);root.setBackground(glass);root.setElevation(dp(s,12));ImageView icon=new ImageView(s);icon.setImageDrawable(item.icon);root.addView(icon,new LinearLayout.LayoutParams(dp(s,30),dp(s,30)));LinearLayout words=new LinearLayout(s);words.setOrientation(1);words.setPadding(dp(s,10),0,dp(s,8),0);TextView title=new TextView(s);title.setText(item.title);title.setTextColor(Color.WHITE);title.setTextSize(13);title.setMaxLines(1);title.setEllipsize(android.text.TextUtils.TruncateAt.END);TextView body=new TextView(s);body.setText(item.text.isEmpty()?item.app:item.text);body.setTextColor(0xffb5cadd);body.setTextSize(11);body.setMaxLines(2);body.setEllipsize(android.text.TextUtils.TruncateAt.END);words.addView(title);words.addView(body);root.addView(words,new LinearLayout.LayoutParams(0,-2,1));TextView x=new TextView(s);x.setText("×");x.setTextSize(24);x.setTextColor(0xffd8edff);x.setGravity(Gravity.CENTER);x.setContentDescription("Скрыть остров");root.addView(x,new LinearLayout.LayoutParams(dp(s,32),dp(s,40)));x.setOnClickListener(v->hide());root.setOnClickListener(v->open(s,item));final float[] down={0};root.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){down[0]=e.getRawY();return true;}if(e.getAction()==MotionEvent.ACTION_UP){if(down[0]-e.getRawY()>dp(s,20))hide();else v.performClick();return true;}return true;});WindowManager.LayoutParams p=new WindowManager.LayoutParams(Math.min(s.getResources().getDisplayMetrics().widthPixels-dp(s,28),dp(s,370)),dp(s,74),WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;p.y=dp(s,31);try{wm.addView(root,p);bubble=root;shownKey=item.key;root.setScaleX(.55f);root.setScaleY(.55f);root.setAlpha(.2f);root.animate().scaleX(1).scaleY(1).alpha(1).setDuration(300).setInterpolator(new android.view.animation.OvershootInterpolator(.5f)).start();handler.postDelayed(close,6500);}catch(Exception ignored){bubble=null;}}
}
